11	         background:var(--bg); color:var(--ink); }
12	  header { padding:20px 24px; border-bottom:1px solid var(--line); background:var(--card); }
13	  header h1 { margin:0; font-size:18px; }
14	  header p { margin:4px 0 0; color:var(--muted); font-size:13px; }
15	  .wrap { max-width:720px; margin:0 auto; padding:24px 16px 80px; }
16	
17	  .saver { background:var(--card); border:1px solid var(--line); border-radius:14px; padding:14px; margin-bottom:22px;
18	           box-shadow:0 1px 2px rgba(0,0,0,.04); }
19	  .saver .row { display:flex; gap:8px; }
20	  .saver input[type=url] { flex:1; padding:12px 14px; font-size:15px; border:1px solid var(--line);
21	                           border-radius:10px; outline:none; }
22	  .saver input[type=url]:focus { border-color:var(--accent); }
23	  .saver button { padding:12px 18px; font-size:15px; font-weight:600; color:#fff; background:var(--accent);
24	                  border:none; border-radius:10px; cursor:pointer; white-space:nowrap; }
