30	  .listhead .count { color:var(--muted); font-size:13px; }
31	
32	  .empty { text-align:center; color:var(--muted); padding:48px 20px; border:1px dashed var(--line);
33	           border-radius:14px; background:var(--card); }
34	  .empty strong { display:block; color:var(--ink); font-size:15px; margin-bottom:4px; }
35	
36	  .card { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px 16px; margin-bottom:10px;
37	          display:flex; gap:12px; align-items:flex-start; animation:pop .18s ease; }
38	  @keyframes pop { from { transform:translateY(-4px); opacity:0; } to { transform:none; opacity:1; } }
