47	</style>
48	</head>
49	<body>
50	<header>
51	  <h1>My Bookmarks</h1>
52	  <p>One place for every link worth keeping.</p>
53	</header>
54	
55	<div class="wrap">
56	  <div class="saver">
57	    <div class="row">
58	      <input id="urlInput" type="url" placeholder="Paste a link and press Save…" autocomplete="off" />
59	      <button id="saveBtn">Save</button>
60	    </div>
61	    <div class="hint">Tip: paste a link, hit Save, and it lands at the top of your list right away.</div>
62	  </div>
63	
64	  <div class="listhead">
65	    <h2>Saved</h2>
66	    <span class="count" id="count"></span>
67	  </div>
68	  <div id="list"></div>
69	</div>
70	
71	<script>
72	  // Prototype only — everything lives in memory and simulates external behaviour.
73	  const bookmarks = [];
74	  let justSavedId = null;
75	  let nextId = 1;
76	
77	  const listEl = document.getElementById('list');
78	  const countEl = document.getElementById('count');
79	  const input = document.getElementById('urlInput');
80	  const btn = document.getElementById('saveBtn');
81	
82	  // Simulated title lookup: real app would read the page's title. Here we guess from the URL.
83	  function guessTitle(url) {
84	    try {
85	      const u = new URL(url);
86	      const host = u.hostname.replace(/^www\./,'');
87	      const seg = u.pathname.split('/').filter(Boolean).pop() || '';
88	      const pretty = seg.replace(/[-_]+/g,' ').replace(/\.\w+$/,'').trim();
89	      if (pretty) return pretty.charAt(0).toUpperCase() + pretty.slice(1) + ' — ' + host;
90	      return host;
91	    } catch(e){ return url; }
92	  }
93	
94	  function fmtWhen(){ return 'just now'; }
95	
96	  function render(){
97	    countEl.textContent = bookmarks.length ? bookmarks.length + (bookmarks.length===1?' link':' links') : '';
98	    if (!bookmarks.length){
99	      listEl.innerHTML = '<div class="empty"><strong>Nothing saved yet</strong>Paste your first link above to get started.</div>';
100	      return;
101	    }
102	    listEl.innerHTML = bookmarks.map(b => `
103	      <div class="card ${b.id===justSavedId?'justsaved':''}">
104	        <div class="favicon">🔖</div>
105	        <div class="body">
106	          <div class="title">${escapeHtml(b.title)}</div>
107	          <div class="url">${escapeHtml(b.url)}</div>
108	          <div class="when">Saved ${b.when}</div>
109	        </div>
110	      </div>`).join('');
111	  }
112	
113	  function escapeHtml(s){ return s.replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
114	
115	  function save(){
116	    let url = input.value.trim();
117	    if (!url) return;
118	    if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
119	    const bm = { id: nextId++, url, title: guessTitle(url), when: fmtWhen() };
120	    bookmarks.unshift(bm);
121	    justSavedId = bm.id;
122	    input.value = '';
123	    render();
124	    input.focus();
125	  }
126	
127	  btn.addEventListener('click', save);
128	  input.addEventListener('keydown', e => { if (e.key === 'Enter') save(); });
129	
130	  render();
131	  input.focus();
132	</script>
133	</body>
134	</html>
