80	<script>
81	  // Prototype only — in memory. A real backend would fetch each page's own
82	  // <title> and summary; here we SIMULATE that lookup.
83	  const bookmarks = [];
84	  let justSavedId = null;
85	  let nextId = 1;
86	  let renamingId = null;
87	
88	  const listEl = document.getElementById('list');
89	  const countEl = document.getElementById('count');
90	  const input = document.getElementById('urlInput');
91	  const btn = document.getElementById('saveBtn');
92	
93	  // Realistic metadata for demo links, so the client sees the true intent.
94	  const KNOWN = {
95	    'en.wikipedia.org/wiki/ancient_rome': {
96	      title: 'Ancient Rome - Wikipedia',
97	      desc: 'The Roman civilization that grew from a city-state on the Italian Peninsula into an empire ruling the Mediterranean world for centuries.'
98	    },
99	    'en.wikipedia.org/wiki/roman_empire': {
100	      title: 'Roman Empire - Wikipedia',
101	      desc: 'The post-Republican period of ancient Rome, ruled by emperors from 27 BC onward across Europe, North Africa and the Near East.'
102	    }
103	  };
104	
105	  function keyFor(url){
106	    try { const u = new URL(url); return (u.hostname.replace(/^www\./,'') + u.pathname.replace(/\/$/,'')).toLowerCase(); }
107	    catch(e){ return url.toLowerCase(); }
108	  }
109	  function hostOf(url){ try { return new URL(url).hostname.replace(/^www\./,''); } catch(e){ return url; } }
110	
111	  // Simulated fetch of the page's real title + summary.
112	  function fetchMeta(url){
113	    const k = keyFor(url);
114	    if (KNOWN[k]) return KNOWN[k];
115	    const host = hostOf(url);
116	    return {
117	      title: 'Page on ' + host,
118	      desc: '(In the finished app, this line shows the page’s own summary so you can find it later by what it’s about.)'
119	    };
120	  }
121	
122	  function faviconMarkup(url){
123	    const host = hostOf(url);
124	    const letter = (host[0] || '?').toUpperCase();
125	    const colors = ['#2f6df6','#e0663f','#3f9f56','#8b5cf6','#d9a441','#d6457f'];
126	    const color = colors[host.length % colors.length];
127	    return `<img class="favicon" src="https://www.google.com/s2/favicons?domain=${encodeURIComponent(host)}&sz=64"
128	             onerror="favFail(this,'${letter}','${color}')" alt="" />`;
129	  }
130	  window.favFail = function(img, letter, color){
131	    const d = document.createElement('div');
132	    d.className = 'favicon fallback';
133	    d.style.background = color;
134	    d.textContent = letter;
135	    img.replaceWith(d);
136	  };
137	
138	  function escapeHtml(s){ return String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
139	
140	  function render(){
141	    countEl.textContent = bookmarks.length ? bookmarks.length + (bookmarks.length===1?' link':' links') : '';
142	    if (!bookmarks.length){
143	      listEl.innerHTML = '<div class="empty"><strong>Nothing saved yet</strong>Paste your first link above to get started.</div>';
144	      return;
145	    }
146	    listEl.innerHTML = bookmarks.map(b => {
147	      if (b.loading){
148	        return `<div class="card">
149	          ${faviconMarkup(b.url)}
150	          <div class="body">
151	            <div class="title fetching">Fetching page details…</div>
152	            <div class="url">${escapeHtml(b.url)}</div>
153	          </div></div>`;
154	      }
155	      const renaming = (b.id === renamingId);
156	      const titleBlock = renaming
157	        ? `<div class="renamebox">
158	             <input id="rename-${b.id}" value="${escapeHtml(b.title)}" />
