161	        : `<div class="title">${escapeHtml(b.title)}</div>`;
162	      return `<div class="card ${b.id===justSavedId?'justsaved':''} ${renaming?'':'clickable'}"
163	                   ${renaming?'':`onclick="openBookmark(${b.id})"`}>
164	        ${faviconMarkup(b.url)}
165	        <div class="body">
166	          ${titleBlock}
167	          <div class="url">${escapeHtml(b.url)}</div>
168	          <div class="desc">${escapeHtml(b.desc)}</div>
169	          <div class="when">Saved just now</div>
170	        </div>
171	        <div class="actions">
172	          ${renaming ? '' : `<button class="iconbtn" onclick="startRename(${b.id}, event)">Rename</button>`}
173	        </div>
174	      </div>`;
175	    }).join('');
176	    if (renamingId){ const el = document.getElementById('rename-'+renamingId); if (el){ el.focus(); el.select(); } }
177	  }
