179	  window.openBookmark = function(id){
180	    const b = bookmarks.find(x=>x.id===id); if(!b) return;
181	    window.open(b.url, '_blank', 'noopener');
182	  };
183	  window.startRename = function(id, ev){ if(ev) ev.stopPropagation(); renamingId = id; render(); };
184	  window.commitRename = function(id){
185	    const el = document.getElementById('rename-'+id);
186	    const b = bookmarks.find(x=>x.id===id);
187	    if (el && b){ const v = el.value.trim(); if (v) b.title = v; }
188	    renamingId = null; render();
189	  };
190	
191	  function save(){
192	    let url = input.value.trim();
193	    if (!url) return;
194	    if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
195	    const bm = { id: nextId++, url, title:'', desc:'', loading:true };
196	    bookmarks.unshift(bm);
197	    justSavedId = bm.id;
198	    input.value = '';
199	    render();
200	    input.focus();
201	    // Simulate the page lookup finishing shortly after save.
202	    setTimeout(() => {
203	      const meta = fetchMeta(bm.url);
204	      bm.title = meta.title; bm.desc = meta.desc; bm.loading = false;
205	      render();
206	    }, 650);
207	  }
208	
209	  btn.addEventListener('click', save);
210	  input.addEventListener('keydown', e => { if (e.key === 'Enter') save(); });
211	
212	  render();
213	  input.focus();
214	</script>
215	</body>
216	</html>
