62	  .iconbtn:hover { border-color:#cbd5e1; color:var(--ink); }
63	  .renamebox { display:flex; gap:6px; }
64	  .renamebox input { flex:1; padding:6px 8px; font-size:15px; border:1px solid var(--accent); border-radius:8px; outline:none; }
65	  mark { background:#fff1a8; color:inherit; border-radius:3px; padding:0 1px; }
66	  .justsaved { border-color:var(--accent); box-shadow:0 0 0 3px rgba(47,109,246,.12); }
67	  .dupflash { animation:flash 1.6s ease; }
68	  @keyframes flash { 0%{ box-shadow:0 0 0 0 rgba(47,109,246,0);} 15%{ box-shadow:0 0 0 4px rgba(47,109,246,.35); border-color:var(--accent);} 100%{ box-shadow:0 0 0 0 rgba(47,109,246,0);} }
69	</style>
70	</head>
71	<body>
72	<header>
73	  <h1>My Bookmarks</h1>
74	  <p>One place for every link worth keeping.</p>
75	</header>
76	
77	<div class="wrap">
78	  <div class="saver">
79	    <div class="row">
80	      <input id="urlInput" type="url" placeholder="Paste a link and press Save…" autocomplete="off" />
81	      <button class="primary" id="saveBtn">Save</button>
82	    </div>
83	    <div class="hint">Tip: paste a link, hit Save, and the app fills in the title and a short summary for you.</div>
84	  </div>
85	
86	  <div class="searchbar">
87	    <span class="mag">🔎</span>
88	    <input id="searchInput" type="search" placeholder="Search your links — title, summary, anything…" autocomplete="off" />
89	    <button class="clear" id="clearBtn" title="Clear">×</button>
90	  </div>
91	
92	  <div id="banner"></div>
93	
94	  <div class="listhead">
95	    <h2 id="listLabel">Saved</h2>
96	    <span class="count" id="count"></span>
97	  </div>
98	  <div id="list"></div>
99	</div>
100	
101	<script>
102	  let justSavedId = null, renamingId = null, flashId = null, bannerTimer = null;
103	  let nextId = 1, query = '';
104	
105	  const listEl = document.getElementById('list');
106	  const countEl = document.getElementById('count');
107	  const listLabel = document.getElementById('listLabel');
108	  const input = document.getElementById('urlInput');
109	  const btn = document.getElementById('saveBtn');
110	  const bannerEl = document.getElementById('banner');
111	  const searchInput = document.getElementById('searchInput');
112	  const clearBtn = document.getElementById('clearBtn');
113	
114	  const KNOWN = {
115	    'en.wikipedia.org/wiki/ancient_rome': { title:'Ancient Rome - Wikipedia',
116	      desc:'The Roman civilization that grew from a city-state on the Italian Peninsula into an empire ruling the Mediterranean world for centuries.' },
117	    'en.wikipedia.org/wiki/roman_empire': { title:'Roman Empire - Wikipedia',
118	      desc:'The post-Republican period of ancient Rome, ruled by emperors from 27 BC across Europe, North Africa and the Near East.' }
119	  };
120	
121	  // Pre-loaded sample links so search feels real.
122	  const bookmarks = [
123	    { id:1, url:'https://en.wikipedia.org/wiki/Ancient_Rome', title:'Ancient Rome - Wikipedia',
124	      desc:'The Roman civilization that grew from a city-state on the Italian Peninsula into an empire ruling the Mediterranean world for centuries.' },
125	    { id:2, url:'https://en.wikipedia.org/wiki/Roman_Empire', title:'Roman Empire - Wikipedia',
126	      desc:'The post-Republican period of ancient Rome, ruled by emperors from 27 BC across Europe, North Africa and the Near East.' },
127	    { id:3, url:'https://cooking.example.com/spaghetti-carbonara', title:'Classic Spaghetti Carbonara',
128	      desc:'A traditional Roman pasta dish made with eggs, pecorino cheese, guanciale and plenty of black pepper.' },
129	    { id:4, url:'https://history.example.com/colosseum', title:'How the Colosseum Was Built',
130	      desc:'The largest amphitheatre ever built, standing in the heart of Rome and completed around 80 AD.' },
131	    { id:5, url:'https://devblog.example.com/js-promises', title:'Understanding JavaScript Promises',
132	      desc:'A practical guide to asynchronous programming in JavaScript using promises and async/await.' }
133	  ];
134	  nextId = 6;
135	
136	  function keyFor(url){
137	    try { const u=new URL(url); return (u.hostname.replace(/^www\./,'')+u.pathname.replace(/\/$/,'')).toLowerCase(); }
138	    catch(e){ return url.toLowerCase(); }
139	  }
140	  function hostOf(url){ try { return new URL(url).hostname.replace(/^www\./,''); } catch(e){ return url; } }
141	
142	  function fetchMeta(url){
143	    const k=keyFor(url); if (KNOWN[k]) return KNOWN[k];
144	    const host=hostOf(url);
145	    return { title:'Page on '+host, desc:'(In the finished app, this line shows the page’s own summary so you can find it later by what it’s about.)' };
146	  }
147	
148	  function faviconMarkup(url){
149	    const host=hostOf(url), letter=(host[0]||'?').toUpperCase();
150	    const colors=['#2f6df6','#e0663f','#3f9f56','#8b5cf6','#d9a441','#d6457f'];
151	    const color=colors[host.length % colors.length];
152	    return `<img class="favicon" src="https://www.google.com/s2/favicons?domain=${encodeURIComponent(host)}&sz=64"
153	             onerror="favFail(this,'${letter}','${color}')" alt="" />`;
154	  }
155	  window.favFail=function(img,letter,color){ const d=document.createElement('div'); d.className='favicon fallback';
156	    d.style.background=color; d.textContent=letter; img.replaceWith(d); };
157	  function escapeHtml(s){ return String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
158	
159	  // Search across title + summary + address. Every typed word must appear somewhere.
160	  function terms(){ return query.toLowerCase().split(/\s+/).filter(Boolean); }
161	  function matches(b){
162	    const hay = (b.title+' '+b.desc+' '+b.url).toLowerCase();
163	    return terms().every(t => hay.includes(t));
164	  }
165	  function highlight(text){
166	    let out = escapeHtml(text);
167	    for (const t of terms()){
168	      if (!t) continue;
169	      const re = new RegExp('('+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');
170	      out = out.replace(re, '<mark>$1</mark>');
171	    }
172	    return out;
173	  }
174	
175	  function showBanner(text){
176	    bannerEl.innerHTML='<div class="banner">'+escapeHtml(text)+'</div>';
177	    if (bannerTimer) clearTimeout(bannerTimer);
178	    bannerTimer=setTimeout(()=>{ bannerEl.innerHTML=''; },4000);
179	  }
180	
181	  function render(){
182	    const q = query.trim();
183	    const shown = q ? bookmarks.filter(matches) : bookmarks;
184	    listLabel.textContent = q ? 'Results' : 'Saved';
185	    countEl.textContent = q
186	      ? shown.length + (shown.length===1?' match':' matches')
187	      : (bookmarks.length ? bookmarks.length+(bookmarks.length===1?' link':' links') : '');
188	    clearBtn.style.display = q ? 'block' : 'none';
189	
190	    if (!bookmarks.length){
191	      listEl.innerHTML='<div class="empty"><strong>Nothing saved yet</strong>Paste your first link above to get started.</div>';
192	      return;
193	    }
194	    if (!shown.length){
195	      listEl.innerHTML='<div class="empty"><strong>No matches for “'+escapeHtml(q)+'”</strong>Try a different word — search looks inside your titles and summaries too.</div>';
196	      return;
197	    }
198	    listEl.innerHTML = shown.map(b => {
199	      if (b.loading){
200	        return `<div class="card" id="card-${b.id}">${faviconMarkup(b.url)}
201	          <div class="body"><div class="title fetching">Fetching page details…</div>
202	          <div class="url">${escapeHtml(b.url)}</div></div></div>`;
203	      }
204	      const renaming=(b.id===renamingId);
205	      const titleBlock = renaming
206	        ? `<div class="renamebox"><input id="rename-${b.id}" value="${escapeHtml(b.title)}" />
207	             <button class="iconbtn" onclick="commitRename(${b.id})">Save</button></div>`
208	        : `<div class="title">${q?highlight(b.title):escapeHtml(b.title)}</div>`;
209	      const cls=['card', b.id===justSavedId?'justsaved':'', b.id===flashId?'dupflash':'', renaming?'':'clickable'].join(' ').trim();
210	      return `<div class="${cls}" id="card-${b.id}" ${renaming?'':`onclick="openBookmark(${b.id})"`}>
211	        ${faviconMarkup(b.url)}
212	        <div class="body">
213	          ${titleBlock}
214	          <div class="url">${escapeHtml(b.url)}</div>
215	          <div class="desc">${q?highlight(b.desc):escapeHtml(b.desc)}</div>
216	        </div>
217	        <div class="actions">${renaming?'':`<button class="iconbtn" onclick="startRename(${b.id}, event)">Rename</button>`}</div>
218	      </div>`;
219	    }).join('');
220	    if (renamingId){ const el=document.getElementById('rename-'+renamingId); if(el){ el.focus(); el.select(); } }
221	  }
222	
223	  window.openBookmark=function(id){ const b=bookmarks.find(x=>x.id===id); if(b) window.open(b.url,'_blank','noopener'); };
224	  window.startRename=function(id,ev){ if(ev) ev.stopPropagation(); renamingId=id; render(); };
225	  window.commitRename=function(id){ const el=document.getElementById('rename-'+id), b=bookmarks.find(x=>x.id===id);
226	    if(el&&b){ const v=el.value.trim(); if(v) b.title=v; } renamingId=null; render(); };
227	
228	  function goToExisting(id, openForEdit){
229	    justSavedId=null; flashId=id; if(openForEdit) renamingId=id;
230	    query=''; searchInput.value='';
231	    render();
232	    const card=document.getElementById('card-'+id); if(card) card.scrollIntoView({behavior:'smooth',block:'center'});
233	    showBanner(openForEdit?'You already saved this one — opened it so you can tweak it.':'You already saved this one — here it is.');
234	    setTimeout(()=>{ flashId=null; },1700);
235	  }
236	  function addNew(url){
237	    const bm={ id:nextId++, url, title:'', desc:'', loading:true };
238	    bookmarks.unshift(bm); justSavedId=bm.id; flashId=null;
239	    query=''; searchInput.value='';
240	    render();
241	    setTimeout(()=>{ const m=fetchMeta(bm.url); bm.title=m.title; bm.desc=m.desc; bm.loading=false; render(); },650);
242	  }
243	  function save(){
244	    let url=input.value.trim(); if(!url) return;
245	    if(!/^https?:\/\//i.test(url)) url='https://'+url;
246	    input.value='';
247	    const dup=bookmarks.find(b=>keyFor(b.url)===keyFor(url));
248	    if(dup){ goToExisting(dup.id,true); input.focus(); return; }
249	    addNew(url); input.focus();
250	  }
251	
252	  btn.addEventListener('click', save);
253	  input.addEventListener('keydown', e=>{ if(e.key==='Enter') save(); });
254	  searchInput.addEventListener('input', ()=>{ query=searchInput.value; render(); });
255	  clearBtn.addEventListener('click', ()=>{ query=''; searchInput.value=''; render(); searchInput.focus(); });
256	
257	  render();
258	</script>
259	</body>
260	</html>
